{"description":"Fetch Bilibili ranking API top video","command":"$ProgressPreference='SilentlyContinue'
$h=@{'User-Agent'='Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Safari/537.36';'Referer'='https://www.bilibili.com/'}
try{
 $r=Invoke-RestMethod -Uri 'https://api.bilibili.com/x/web-interface/ranking/v2?rid=0&type=all' -Headers $h -TimeoutSec 20
 $r.code
 $list=$r.data.list
 $list | Select-Object -First 5 | ForEach-Object { "{0}`t{1}`t{2}`t{3}" -f $_.title,$_.owner.name,$_.tname,$_.bvid }
}catch{ "ERR: $($_.Exception.Message)" }"}

